// Momento site script
// Updates the clock and stats based on the repository state

// Update the live clock
function updateClock() {
  const now = new Date();
  const utcString = now.toISOString().replace('T', ' ').replace('Z', '');
  document.getElementById('momento-clock').textContent = `Current UTC: ${utcString}`;
}

