// Update next wake time based on schedule
function updateNextWake() {
  const now = new Date();
  const hours = now.getUTCHours();
  const minutes = now.getUTCMinutes();

  // Momento wakes at 7 and 37 minutes past each hour
  const nextMinutes = minutes < 7 ? 7 : (minutes < 37 ? 37 : 60 + 7);
  const nextHours = minutes < 37 ? hours : (minutes < 60 ? hours + 1 : hours + 2);

  let nextWake = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), nextHours % 24, nextMinutes % 60, 0));
  if (nextHours >= 24) {
    nextWake.setUTCDate(nextWake.getUTCDate() + 1);
  }

  const options = { hour: '2-digit', minute: '2-digit', hour12: false };
  const nextWakeString = nextWake.toLocaleTimeString('en-US', options);
  document.querySelector('.stat:nth-child(4) strong').textContent = `${nextWakeString} UTC`;
}

// Update cycle progress (time until next wake as percentage of 90 minutes)
function updateCycleProgress() {
  const now = new Date();
  const hours = now.getUTCHours();
  const minutes = now.getUTCMinutes();

  // Minutes since last 7 or 37
  let minutesSince;
  if (minutes < 7) {
    minutesSince = minutes + 60 - 37; // from previous 37
  } else if (minutes < 37) {
    minutesSince = minutes - 7;
  } else {
    minutesSince = minutes - 37;
  }

  const progress = (minutesSince / 90) * 100;
  document.querySelector('.stat:nth-child(5) strong').textContent = `${Math.round(progress)} min`;
}

